// Arduino Sketch
// Подключение библиотеки для управления RGB LED
#include <Adafruit_NeoPixel.h>

// === НАСТРОЙКИ ПИНОВ ===
#define MOTION_SENSOR_PIN 4    // Датчик движения (HC-SR501)
#define RELAY_PIN 5            // Реле
#define RGB_LED_PIN 48         // Пин встроенного RGB (указываем для DevKitC-1)
#define NUM_LEDS 1             // Количество RGB светодиодов

// === ПАРАМЕТРЫ ===
#define RELAY_ON_TIME 5000     // Время включения реле в мс (5 секунд)

// === ПЕРЕМЕННЫЕ ===
Adafruit_NeoPixel rgb = Adafruit_NeoPixel(NUM_LEDS, RGB_LED_PIN, NEO_GRB + NEO_KHZ800);
unsigned long relayStartTime = 0;
bool relayActive = false;
bool motionDetected = false;

// Состояния для мерцания
unsigned long lastBlinkTime = 0;
bool ledState = false;

void setup() {
  Serial.begin(115200);
  delay(100);

  // Настройка пинов
  pinMode(MOTION_SENSOR_PIN, INPUT);
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, HIGH); // Реле выключено (если LOW-активное)

  // Инициализация RGB
  rgb.begin();
  rgb.setBrightness(30); // Яркость 30% (чтобы не слепило)
  rgb.show();

  Serial.println("=== Система запущена ===");
  Serial.println("Ожидание датчика движения...");
}

void loop() {
  // 1. Чтение датчика движения
  int motionValue = digitalRead(MOTION_SENSOR_PIN);

  // 2. Обработка движения
  if (motionValue == HIGH && !motionDetected) {
    // Движение обнаружено!
    motionDetected = true;
    relayActive = true;
    relayStartTime = millis();
    digitalWrite(RELAY_PIN, LOW); // Включаем реле
    Serial.println("=== ДВИЖЕНИЕ ОБНАРУЖЕНО! Реле включено ===");
  }

  // 3. Таймер для реле (5 секунд)
  if (relayActive && (millis() - relayStartTime >= RELAY_ON_TIME)) {
    digitalWrite(RELAY_PIN, HIGH); // Выключаем реле
    relayActive = false;
    motionDetected = false; // Сбрасываем флаг, чтобы можно было снова сработать
    Serial.println("Реле выключено (таймер 5 сек)");
  }

  // 4. Управление RGB LED
  updateRGB();

  delay(10); // Небольшая задержка для стабильности
}

void updateRGB() {
  if (relayActive) {
    // === РЕЖИМ: КРАСНЫЙ С МИГАНИЕМ 1 Гц ===
    unsigned long currentMillis = millis();
    // Меняем состояние каждые 500 мс (частота 1 Гц)
    if (currentMillis - lastBlinkTime >= 500) {
      lastBlinkTime = currentMillis;
      ledState = !ledState;
    }

    if (ledState) {
      rgb.setPixelColor(0, rgb.Color(255, 0, 0)); // Красный
    } else {
      rgb.setPixelColor(0, rgb.Color(0, 0, 0));   // Выключен
    }

  } else {
    // === РЕЖИМ: ЦИАНОВЫЙ (ГОЛУБОЙ) С МЕДЛЕННЫМ МЕРЦАНИЕМ ===
    // Используем синусоидальное дыхание (период ~3 секунды)
    float brightness = (sin(millis() / 1000.0 * 1.5) + 1) / 2; // от 0 до 1
    // Яркость от 10 до 30 (чтобы не было полного выключения)
    int bright = 10 + (int)(brightness * 20);
    rgb.setBrightness(bright);
    rgb.setPixelColor(0, rgb.Color(0, 255, 255)); // Циановый
  }

  rgb.show();
}
